import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"The kernel IR is a Term plus kit-declared ops","description":"","frontmatter":{"title":"The kernel IR is a `Term` plus kit-declared ops","type":"adr","date":"2026-10-29T00:00:00.000Z","status":"implemented","applies_to":"`lib-kernel-ir` (ops, terms, denotations), `kernelopt` (search), `graphopt/bench` (gate)"},"headers":[],"relativePath":"handl/project/adrs/0165-kernel-ir-is-term-plus-ops.md","filePath":"vendored/handl/project/adrs/0165-kernel-ir-is-term-plus-ops.md"}'),a={name:`handl/project/adrs/0165-kernel-ir-is-term-plus-ops.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0165-the-kernel-ir-is-a-term-plus-kit-declared-ops" tabindex="-1">ADR-0165: The kernel IR is a <code>Term</code> plus kit-declared ops <a class="header-anchor" href="#adr-0165-the-kernel-ir-is-a-term-plus-kit-declared-ops" aria-label="Permalink to “ADR-0165: The kernel IR is a Term plus kit-declared ops”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><blockquote><p>Numbered 0165, not the 0160 the M1 build list asked for: <code>0160</code> is already <code>lib-repos-are-language-packages</code>, and numbers are never reused (ADR-0161 rule 6).</p></blockquote><ol><li>A kernel body is a <strong><code>Term</code></strong>: an op name applied to arguments, where arguments are other terms or leaves from an environment. The IR is data.</li><li>The <strong>op set is closed at nine</strong> — <code>tile_load</code>, <code>unpack_i4</code>, <code>dequant</code>, <code>dot</code>, <code>split</code>, <code>stage</code>, <code>reduce</code>, <code>store</code>, <code>bias</code>. Adding a tenth is a finding about the platform, not a commit.</li><li>Every op declares four things: a <strong>signature</strong>, a <strong>grade</strong> (<code>EXACT</code> or <code>ROUNDS</code>), a <strong>cost</strong> (bytes, ops, launches), and a <strong>torch denotation</strong> — one reference function per op.</li><li>Two terms are equal iff their <strong>denotations</strong> are equal, checked by <code>bench.benchkit.equality.cosine_gate</code> against an <strong>external</strong> incumbent (<code>awq_gemm</code>). A term is never gated against another term we wrote.</li><li>The IR carries <strong>no kernel combinators</strong>. It enters the platform as a language and is interpreted by an engine (<code>compile-triton</code>); the kernel&#39;s six combinators stay closed.</li><li>Cost is a <strong>hard bound only</strong> — roofline floor and legality pruning. It never ranks feasible candidates; the referee does.</li><li>The denotation is the <em>meaning</em>, not the <em>schedule</em>. Two equal terms may differ 3× in time and that is the point of searching over them.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The AWQ nibble-order bug passed a full round of &quot;exactness&quot; checks because kernel and reference shared an assumption (cosine 0.21 against <code>awq_gemm</code>, P21/P22). A body that is data, with a declared per-op denotation and an external gate, makes that class of failure a test rather than a memory. It also puts the search over something a human can read: <code>split_k = 4</code> is four <code>split</code> terms with a provably equal composed denotation, not a flag someone hopes is safe.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>A tenth op for pipelining or shared-memory residency</strong> — the review&#39;s strongest objection (the nine ops cannot express scheduling); rejected for M1 because the codegen leg is unproven and a schedule language that cannot beat 30 lines of Triton is decoration. Revisit after M1.</li><li><strong>Proving schedules equal</strong> — denotations prove meaning only; cost is measured, never derived (ADR: residual opacity).</li><li><strong>An open op registry</strong> — <code>OPS</code> is a frozen mapping; extension is an ADR.</li><li><strong>Ranking candidates by the cost model</strong> — measured to contradict deploy ranking on three of four shapes (P10/P12).</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>lib-kernel-ir/src/lib_kernel_ir/ops.py</code> — <code>OPS</code>, the frozen nine, each with signature/grade/cost/denotation.</li><li><code>lib-kernel-ir/tests/test_ops.py</code> — nine denotation tests + &quot;all four <code>split_k</code> terms denote the same function&quot; at cosine ≥ 0.99999.</li><li><code>graphopt/bench/benchkit/equality.py</code> — the external-incumbent gate.</li><li><code>kernelopt/src/mlopt_kernel/search.py</code> — enumerates terms, applies the gate, prunes on cost, measures with the referee.</li></ul>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};